import React from 'react';

import { useCurrentTheme } from '../../../../core/hooks/useCurrentTheme.js';
import { AreaIndicator } from '../../../core/components/annotations-atoms/components/indicators/AreaIndicator.js';
import { LineIndicator } from '../../../core/components/annotations-atoms/components/indicators/LineIndicator.js';
import { getMarkerBrightnessBasedOnState } from '../../../core/components/annotations-atoms/functions/get-marker-brightness-based-on-state.js';
import { MarkerInteractionState } from '../../../core/components/annotations-atoms/types/marker.js';
import { isTimeframe } from '../../../core/components/annotations-timeseries/functions/is-timeframe.js';
import { markerGroupKey } from '../../../core/components/annotations-timeseries/functions/marker-group-key.js';
import { BrightnessFilter } from '../../../core/components/BrightnessFilter.js';
import { SVGPlotLayout } from '../../../core/components/chart-grid/ChartGridRoot.js';
import { useGridPlotSize } from '../../../core/components/chart-grid/hooks/useGridPlotSize.js';
import { useTimeseriesChartAnnotationsData } from '../../hooks/useTimeseriesChartAnnotationsData.js';
import { useXScales } from '../../hooks/useXScale.js';
import { IndicatorData } from '../../types/indicators.js';
import { filterIndicatorsOutOfBounds } from '../../utils/filter-indicators-out-of-bounds.js';

interface IndicatorsRendererProps {
  start: Date;
  end?: Date;
  color: string;
  state: MarkerInteractionState;
}

const IndicatorsRenderer = ({
  start,
  end,
  color,
  state,
}: IndicatorsRendererProps) => {
  const { currentScale: xScale } = useXScales();
  const { height } = useGridPlotSize();
  const theme = useCurrentTheme();
  const slope = getMarkerBrightnessBasedOnState(theme, state);
  let ShapeComponent;
  const brightnessFilterId = `brightness_${markerGroupKey(start, end)}`;

  const filter = `url(#${brightnessFilterId})`;

  const timelapse = { start, end };
  const x0 = xScale(timelapse.start) ?? 0;

  if (isTimeframe(timelapse)) {
    const x1 = xScale(timelapse.end) ?? 0;
    const width = x1 - x0;
    ShapeComponent = AreaIndicator({
      x: x0,
      width,
      height,
      color,
      filter,
    });
  } else {
    ShapeComponent = LineIndicator({ x: x0, height, color, filter });
  }

  return (
    <>
      <BrightnessFilter id={brightnessFilterId} slope={slope} />
      {ShapeComponent}
    </>
  );
};

const extractUniqueIndicatorsByPriority = (indicators: IndicatorData[][]) => {
  const indicatorsByTrack: [string, IndicatorData][][] = [];
  indicators.forEach((track, index) => {
    indicatorsByTrack[index] = [];
    const map = track.reduce((uniqueIndicators, indicator) => {
      const key = markerGroupKey(indicator.start, indicator.end);

      if (!uniqueIndicators.has(key)) {
        uniqueIndicators.set(key, indicator);
      } else {
        const value = uniqueIndicators.get(key)!;

        if (indicator.priority) {
          if (!value.priority || value.priority < indicator.priority) {
            uniqueIndicators.set(key, indicator);
          }
        }
      }

      return uniqueIndicators;
    }, new Map<string, IndicatorData>());
    indicatorsByTrack[index] = Array.from(map.entries());
  });

  return indicatorsByTrack;
};

export const AnnotationsIndicators = () => {
  const { indicators } = useTimeseriesChartAnnotationsData();
  const { currentScale: xScale } = useXScales();

  const filteredIndicators = filterIndicatorsOutOfBounds(
    indicators,
    xScale.domain(),
  );
  const uniqueIndicators =
    extractUniqueIndicatorsByPriority(filteredIndicators);

  return (
    <SVGPlotLayout>
      {uniqueIndicators.map((track) =>
        track.map(([key, indicator]) => (
          <IndicatorsRenderer key={key} {...indicator} />
        )),
      )}
    </SVGPlotLayout>
  );
};
